function ensureMoneyModal(){if(byId('v44MoneyModal'))return;const el=document.createElement('div');el.className='modal';el.id='v44MoneyModal';el.innerHTML=`<div class="modal-card" style="max-width:620px"><div class="modal-head"><h3 id="v44MoneyTitle">Record payment</h3><button class="secondary" type="button" data-v44-close>Close</button></div><div class="v44-modal-grid"><div class="field wide"><label>Invoice</label><select id="v44MoneyInvoice"></select></div><div class="field"><label>Date</label><input id="v44MoneyDate" type="date"></div><div class="field"><label>Amount incl. VAT (€)</label><input id="v44MoneyAmount" type="text" inputmode="decimal" placeholder="0,00"><small id="v44MoneyLimit" class="v44-note"></small></div><div class="field"><label>Method</label><select id="v44MoneyMethod"><option>Bank</option><option>Card</option><option>Cash</option><option>Other</option></select></div><div class="field"><label>Reference</label><input id="v44MoneyReference"></div><div class="field wide" id="v44CreditReasonField" hidden><label>Credit reason</label><input id="v44CreditReason"></div></div><div class="modal-foot"><button class="green" id="v44MoneySave">Save</button></div></div>`;document.body.appendChild(el);el.querySelector('[data-v44-close]').onclick=()=>el.classList.remove('open');el.onclick=e=>{if(e.target===el)el.classList.remove('open')}}
function parseMoneyEntry(v){let s=String(v??'').trim().replace(/\s|€/g,'');if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');else if(s.includes(','))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?A.round2(n):0}
function paymentById(id){return data.payments.find(p=>String(p.id||p['Payment ID'])===String(id))}
