function saveMoney(kind,paymentId=null){if(!ensurePeriodEditable(kind==='credit'?'create a credit note':'record a payment'))return;const id=byId('v44MoneyInvoice').value,inv=rowRef(id),amount=parseMoneyEntry(byId('v44MoneyAmount').value),date=byId('v44MoneyDate').value;if(!inv||!date||amount<=0){alert('Choose an invoice, date and positive amount. Use 500,00 or 500.00 for five hundred euros.');return}if(kind==='payment'){const existing=paymentId?paymentById(paymentId):null,sameInvoice=existing&&(existing.invoiceId===id||existing['Invoice #']===inv['Invoice #']),available=A.round2(stateFor(inv).outstanding+(sameInvoice?A.num(existing.amount??existing.Amount):0));if(amount>available+.009){alert(`Payment cannot exceed the invoice balance.\n\nAvailable: ${money(available)}\nEntered: ${money(amount)}`);return}const row={...(existing||{}),id:existing?.id||existing?.['Payment ID']||A.makeId('PAY'),invoiceId:id,'Invoice #':inv['Invoice #'],date,amount:A.round2(amount),method:byId('v44MoneyMethod').value,reference:byId('v44MoneyReference').value.trim()};if(existing)data.payments[data.payments.indexOf(existing)]=row;else data.payments.push(row)}else{const t=A.invoiceTotals(inv),ratio=Math.min(1,amount/t.gross);data.creditNotes.push({id:A.makeId('CRN'),invoiceId:id,'Invoice #':inv['Invoice #'],date,gross:A.round2(amount),net:A.round2(t.net*ratio),vat:A.round2(amount-t.net*ratio),reason:byId('v44CreditReason').value.trim()});}byId('v44MoneyModal').classList.remove('open');persist()}
function removeV44Payment(paymentId){if(!ensurePeriodEditable('remove a payment'))return;const payment=paymentById(paymentId);if(!payment)return;const inv=rowRef(payment.invoiceId),amount=A.num(payment.amount??payment.Amount);if(!confirm(`Remove the ${money(amount)} payment from invoice ${payment['Invoice #']||inv?.['Invoice #']||''}?\n\nThe removal will remain visible in the audit/recovery list.`))return;data.payments.splice(data.payments.indexOf(payment),1);data.deleted=data.deleted||[];data.deleted.push({'Deleted at':new Date().toISOString(),Type:'Customer payment','Record ID':payment.id||payment['Payment ID'],'Customer / Supplier':inv?.Customer||'','Description':`Removed payment for ${payment['Invoice #']||inv?.['Invoice #']||''}`,Gross:amount,VAT:0,Net:amount,Status:'Removed','Original record':payment});persist()}
